-- =============================================================================
-- V190 — Domestic (CASH) booking rates: rate card PUNE_CASH_2025 "Pune Cash" (from PUNE, GST 0 %), 68 lanes.
-- Generated by a script from the card set up on dev on 2026-11-28 from the owner's CASH_BOOKING_RATES.xlsx; do not edit.
--
-- The sheet, as loaded: 1000 rows = one 500-row block pasted twice; 162 distinct lines. Kerala rows dropped (owner: price
-- Kerala as South). "Addition 500GM" (Premium) = rate per extra 0.5 kg (owner's choice); "Per Kg" = per extra 1 kg.
-- Companies OCCPL and OCCPL_COURIER, using the zones V188 created (PUNE … NORTH_EAST, NORTH, SOUTH, EAST, WEST, CENTRAL,
-- METRO) and the company's service types SRF (Surface), AIR, SURFACE_CARGO, PRM (Premium) and package types DOCUMENT and
-- NON-DOC, all matched by code. A lane whose zone, service or package type the company lacks is skipped.
-- A company is skipped when it already has a PUNE_CASH_2025 card or an ACTIVE company card from PUNE (dev: set up by hand).
-- =============================================================================

SET @now = UTC_TIMESTAMP(6);

DROP TEMPORARY TABLE IF EXISTS tmp_v190_slab;
CREATE TEMPORARY TABLE tmp_v190_slab (
    to_zone VARCHAR(30) NOT NULL, service VARCHAR(30) NOT NULL, package VARCHAR(30) NOT NULL,
    w_from DECIMAL(10,3) NOT NULL, w_to DECIMAL(10,3) NOT NULL, rate_type VARCHAR(15) NOT NULL,
    rate DECIMAL(12,2) NOT NULL, step_kg DECIMAL(6,3) NULL
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

-- Companies to load: OCCPL / OCCPL_COURIER with a PUNE zone, no PUNE_CASH_2025 card and no active company card from PUNE.
DROP TEMPORARY TABLE IF EXISTS tmp_v190_co;
CREATE TEMPORARY TABLE tmp_v190_co (company_id BINARY(16) NOT NULL PRIMARY KEY, card_id BINARY(16) NOT NULL, pune_id BINARY(16) NOT NULL)
    ENGINE = InnoDB DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;
SELECT c.company_id, UNHEX(REPLACE(UUID(), '-', '')), z.id
FROM companies c
JOIN tariff_zones z ON z.company_id = c.company_id AND z.code = 'PUNE' AND z.deleted = FALSE
WHERE c.company_code IN ('OCCPL', 'OCCPL_COURIER') AND c.deleted = FALSE
  AND NOT EXISTS (SELECT 1 FROM tariff_rate_cards rc WHERE rc.company_id = c.company_id AND rc.deleted = FALSE
                  AND (rc.code = 'PUNE_CASH_2025' OR (rc.customer_id IS NULL AND rc.status = 'ACTIVE' AND rc.from_zone_id = z.id)));

                               volumetric_divisor, total_rounding, description, status, created_at, updated_at, deleted, version)
SELECT t.card_id, t.company_id, 'PUNE_CASH_2025', 'Pune Cash', t.pune_id, NULL, '2025-04-01', NULL, 0.00, NULL, 'NEAREST_RUPEE',
       'Domestic (CASH) booking rates from CASH_BOOKING_RATES.xlsx; Kerala priced as South (V190)', 'ACTIVE', @now, @now, FALSE, 0
FROM tmp_v190_co t;

                               weight_to_kg, rate_type, rate, step_kg, created_at, updated_at, deleted, version)
SELECT UNHEX(REPLACE(UUID(), '-', '')), t.company_id, t.card_id, z.id, st.id, pt.id, s.w_from, s.w_to, s.rate_type, s.rate,
       s.step_kg, @now, @now, FALSE, 0
FROM tmp_v190_co t
JOIN tmp_v190_slab s
JOIN tariff_zones z ON z.company_id = t.company_id AND z.code = s.to_zone AND z.deleted = FALSE
JOIN master_service_types st ON st.company_id = t.company_id AND st.code = s.service AND st.deleted = FALSE
JOIN master_package_types pt ON pt.company_id = t.company_id AND pt.code = s.package AND pt.deleted = FALSE;

DROP TEMPORARY TABLE tmp_v190_co;
DROP TEMPORARY TABLE tmp_v190_slab;
